#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Git Bash en Windows: gh recién instalado con winget aún no está en el PATH de esta terminal.
[[ -x "/c/Program Files/GitHub CLI/gh.exe" ]] && PATH="/c/Program Files/GitHub CLI:$PATH"

TOTAL_STAGES=7

banner "DecideAqui: GitHub + Supabase + Vercel"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "GitHub CLI"
say "Usaremos la CLI de GitHub (gh) para guardar los secretos de CI."
if ! command -v gh >/dev/null 2>&1; then
  warn "gh no está instalado. En Windows, en otra terminal:"
  step "winget install --id GitHub.cli"
  step "Cierra y abre la terminal, y vuelve a ejecutar este wizard."
  note "Si sigues sin gh, el wizard guardará todo en .env y te dirá qué secretos cargar a mano."
elif ! gh auth status >/dev/null 2>&1; then
  step "Inicia sesión: se abrirá el navegador."
  if confirm "¿Ejecutar 'gh auth login' ahora?"; then gh auth login --web --git-protocol https; fi
fi
pause "Enter para continuar"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub: repositorio"
say "Crea un repositorio vacío llamado comparador-ecuador (sin README ni .gitignore)."
open_url "https://github.com/new"
step "Owner: tu usuario · Name: el que quieras · Private o Public · sin README, .gitignore ni licencia."
note "Público: Actions sin límite de minutos. Privado: 2000 min/mes (la ingesta diaria usa ~330)."
warn "Vercel Hobby solo despliega commits cuyo autor sea la cuenta dueña del proyecto."
step "Usa en este repositorio el email noreply de esa cuenta (GitHub → Settings → Emails):"
step "  git config user.email \"<id>+<usuario>@users.noreply.github.com\""
ask GITHUB_REPO "Escribe el repositorio como usuario/nombre:"
write_env GITHUB_REPO "$GITHUB_REPO"
if [[ ! -d .git ]] && confirm "¿Inicializar git aquí y conectar con github.com/$GITHUB_REPO?"; then
  git init -b main >/dev/null
  git remote add origin "https://github.com/$GITHUB_REPO.git"
  say "Listo. Haz tu primer commit y 'git push -u origin main' cuando quieras."
fi
export GH_REPO="$GITHUB_REPO"   # gh secret/variable usarán este repositorio
pause "Enter para continuar"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: proyecto"
say "Crea el proyecto de base de datos."
open_url "https://supabase.com/dashboard/new"
step "Name: el que quieras · Region: East US (North Virginia), junto a Vercel iad1 (ADR 0005)."
step "Security: DESMARCA 'Automatically expose new tables' y MARCA 'Enable automatic RLS'."
note "Los permisos de la API se conceden a mano en la migración 0400; con la exposición automática sobrarían."
step "Genera una contraseña de base de datos y cópiala ANTES de crear el proyecto."
note "Mejor solo letras y números: los símbolos hay que codificarlos dentro de la URI de conexión."
ask_secret SUPABASE_DB_PASSWORD "Pega la contraseña de la base de datos:"
write_env SUPABASE_DB_PASSWORD "$SUPABASE_DB_PASSWORD"   # solo local: CI usa DATABASE_URL
step "Cuando el proyecto esté listo, la URL del panel será supabase.com/dashboard/project/<ref>."
ask SUPABASE_PROJECT_REF "Pega el <ref> del proyecto (20 letras):"
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
write_env NEXT_PUBLIC_SUPABASE_URL "https://$SUPABASE_PROJECT_REF.supabase.co"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: claves de API"
open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF/settings/api-keys"
step "Copia la Publishable key (empieza por sb_publishable_). Es pública: va al navegador."
ask NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "Pega la publishable key:"
write_env NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "$NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"
note "No hace falta ninguna Secret key (sb_secret_): ni la web ni la ingesta la usan. No la crees."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Supabase: conexión para la ingesta"
say "El worker de GitHub Actions se conecta directo a Postgres por el pooler (ADR 0004)."
open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF?showConnect=true"
step "Botón Connect → Connection string → Session pooler (puerto 5432)."
step "Copia la URI y reemplaza [YOUR-PASSWORD] por la contraseña de la etapa 3."
warn "Pega UNA sola URI, sin corchetes. Si pegas la plantilla y la URI juntas, la conexión falla."
ask_secret DATABASE_URL "Pega la URI postgresql://… ya con la contraseña:"
write_env DATABASE_URL "$DATABASE_URL"
set_secret DATABASE_URL "$DATABASE_URL"

# (Sin token de Supabase: el workflow de migraciones usa "supabase db push --db-url" con DATABASE_URL.)

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Vercel: importar el proyecto"
say "Conecta el repositorio para tener una vista previa por pull request y producción en main."
open_url "https://vercel.com/new"
step "Import Git Repository → $GITHUB_REPO."
step "Root Directory: apps/web (Edit → elige la carpeta). Framework Preset: Next.js."
step "Environment Variables: añade solo NEXT_PUBLIC_SUPABASE_URL y NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY."
step "  Type: Config (no Secret: con el prefijo NEXT_PUBLIC_ Vercel rechaza Secret). Environments: Production y Preview."
warn "En .env los valores van entre comillas simples. En Vercel pega el valor SIN las comillas."
note "La región iad1 (junto a Supabase) ya viene fijada en apps/web/vercel.json."
note "Plan Hobby: solo uso no comercial. Si el comparador cobra por salidas, necesitas Pro (ADR 0005)."
pause "Enter cuando hayas importado el proyecto"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Vercel: acceso de k6 a las vistas previas"
say "Las vistas previas piden inicio de sesión; k6 entra con un secreto de bypass."
open_url "https://vercel.com/dashboard"
step "Proyecto → Settings → Deployment Protection → Protection Bypass for Automation → crear secreto."
note "Deja el valor que genera Vercel, pulsa Save y cópialo con el botón de copiar."
ask_secret VERCEL_AUTOMATION_BYPASS_SECRET "Pega el secreto de bypass:"
write_env VERCEL_AUTOMATION_BYPASS_SECRET "$VERCEL_AUTOMATION_BYPASS_SECRET"
set_secret VERCEL_AUTOMATION_BYPASS_SECRET "$VERCEL_AUTOMATION_BYPASS_SECRET"

finish
say "Siguiente: sigue GUIA-REPLICA.md desde 'Primer despliegue' (push, seed, primera ingesta)."
}

run_wizard "$@"; exit
